const AI_METADATA_MARKERS = [
  "trainedalgorithmicmedia",
  "compositewithtrainedalgorithmicmedia",
  "ai-generated",
  "ai generated",
  "generated by ai",
  "dall-e",
  "dall·e",
  "midjourney",
  "stable diffusion",
  "adobe firefly",
];

const SAMPLE_BYTES = 1024 * 1024;

async function readableSample(file: File): Promise<string> {
  const head = file.slice(0, SAMPLE_BYTES);
  const tail =
    file.size > SAMPLE_BYTES
      ? file.slice(Math.max(SAMPLE_BYTES, file.size - SAMPLE_BYTES))
      : null;
  const samples = tail ? [head, tail] : [head];
  const chunks = await Promise.all(samples.map((blob) => blob.arrayBuffer()));
  const decoder = new TextDecoder("latin1");
  return chunks.map((chunk) => decoder.decode(chunk)).join("\n").toLowerCase();
}

/** Detect strong embedded markers for AI-generated or AI-composited media. */
export async function hasAiContentMetadata(file: File): Promise<boolean> {
  try {
    const metadata = await readableSample(file);
    return AI_METADATA_MARKERS.some((marker) => metadata.includes(marker));
  } catch {
    return false;
  }
}
